mapper.select:
SELECT sod.id, sod.main_id, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.warehouse_location, sod.is_close, sod.remark, sod.source_detail_id, so.approve_status, so.invalid_status FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE AND so.invalid_status = FALSE
AND sod.source_detail_id in
#{id}

SELECT sod.id, sod.main_id, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.warehouse_location, sod.is_close, sod.remark, sod.source_detail_id, sod.so_detail_id, so.approve_status, so.invalid_status, so.so_id, so.track_no FROM so_outstock so INNER JOIN so_outstock_detail sod ON sod.main_id = so.id AND so.is_deleted=FALSE WHERE sod.is_deleted = FALSE AND so.invalid_status = FALSE
AND so.so_id IN
#{id}

select sod.id, sod.main_id, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.warehouse_location, sod.is_close, sod.remark, sod.source_detail_id, so.approve_status, sod.so_detail_id, so.so_id from so_outstock so inner join so_outstock_detail sod on sod.main_id = so.id and sod.is_deleted=FALSE where so.is_deleted = false and so.invalid_status = false
and sod.so_detail_id in
#{id}

SELECT so.id, sod.sku_id, sod.sku_no, SUM(sod.actual_qty) AS deliveryQty FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id = sod.main_id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE
AND sod.main_id = #{mainId}
GROUP BY so.id, sod.sku_id, sod.sku_no

SELECT sod.sku_id AS skuId, MAX(so.bill_date) AS billDate FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.approve_status = 'approve' AND sod.sku_id IN
#{skuId}
and so.is_deleted = FALSE and sod.is_deleted = FALSE GROUP BY sod.sku_id

with so_base as materialized ( select id, code, so_id, so_code, source_type, source_code, sales_org_id, sales_org_name, bill_date, warehouse_id, warehouse_name, customer_id from so_outstock where is_deleted = false and approve_status = 'approve'
and bill_date >= #{param.startTime}
and bill_date < #{param.endTime}
) select so.id as soOutstockId, so.code as soOutstockCode, so.so_id as soId, so.so_code as soCode, sod.platform_code as platformCode, so.source_type as sourceType, so.source_code as sourceCode, so.sales_org_id as salesOrgId, so.sales_org_name as salesOrgName, so.bill_date as soOutstockDate, sod.id as soOutstockDetailId, sod.so_detail_id as soDetailId, sod.sku_id as skuId, sod.sku_no as skuNo, sod.actual_qty as actualQty, so.warehouse_id as warehouseId, so.warehouse_name as warehouseName, so.customer_id as customerId from so_base so join so_outstock_detail sod on so.id = sod.main_id and sod.is_deleted = false where sod.platform_code like 'KOL%' union select so.id as soOutstockId, so.code as soOutstockCode, so.so_id as soId, so.so_code as soCode, sod.platform_code as platformCode, so.source_type as sourceType, so.source_code as sourceCode, so.sales_org_id as salesOrgId, so.sales_org_name as salesOrgName, so.bill_date as soOutstockDate, sod.id as soOutstockDetailId, sod.so_detail_id as soDetailId, sod.sku_id as skuId, sod.sku_no as skuNo, sod.actual_qty as actualQty, so.warehouse_id as warehouseId, so.warehouse_name as warehouseName, so.customer_id as customerId from so_base so join so_info si on si.id = so.so_id and si.is_deleted = false and si.source_type = 'kolB2bApplication' join so_outstock_detail sod on so.id = sod.main_id and sod.is_deleted = false union select so.id as soOutstockId, so.code as soOutstockCode, so.so_id as soId, so.so_code as soCode, sod.platform_code as platformCode, so.source_type as sourceType, so.source_code as sourceCode, so.sales_org_id as salesOrgId, so.sales_org_name as salesOrgName, so.bill_date as soOutstockDate, sod.id as soOutstockDetailId, sod.so_detail_id as soDetailId, sod.sku_id as skuId, sod.sku_no as skuNo, sod.actual_qty as actualQty, so.warehouse_id as warehouseId, so.warehouse_name as warehouseName, so.customer_id as customerId from so_base so join so_b2c sb on sb.id = so.so_id and sb.is_deleted = false and sb.source_type = 'kolB2cApplication' join so_outstock_detail sod on so.id = sod.main_id and sod.is_deleted = false;
